;(()=>{const key='jardeo-guide-seen';const steps=[['🌿','Bienvenue dans TERROLOGIS','Votre carnet de jardin pour prendre soin de vos plantes toute l’année.'],['🪴','Mes plantes','Ajoutez vos plantes manuellement ou depuis le catalogue de 100 plantes. Retrouvez leurs conseils et votre carnet.'],['📸','Identifier une plante','Ouvrez Scanner et choisissez une photo. Vérifiez les suggestions avant d’ajouter une plante.'],['🏡','Plan de mon jardin','Aménagez votre grille puis sélectionnez vos plantes pour les placer sur le plan.'],['📅','Organisez votre jardin','Consultez le calendrier, les rappels et la météo de votre localisation. Pensez à sauvegarder vos données dans les réglages.']];let i=0;const d=document.createElement('dialog');d.className='welcome-guide';d.setAttribute('aria-label','Guide de première utilisation');document.body.append(d);function finish(){try{localStorage.setItem(key,'1')}catch{}d.close()}function draw(){const [emoji,title,desc]=steps[i];d.innerHTML='<div class="guide-progress">Étape '+(i+1)+' sur '+steps.length+'</div><progress max="'+steps.length+'" value="'+(i+1)+'"></progress><div class="guide-emoji">'+emoji+'</div><h2>'+title+'</h2><p>'+desc+'</p><div class="guide-actions"><button id="guide-skip">Passer</button>'+(i?'<button id="guide-back">Précédent</button>':'')+'<button class="primary" id="guide-next">'+(i===steps.length-1?'Commencer à jardiner':'Suivant')+'</button></div>';d.querySelector('#guide-skip').onclick=finish;d.querySelector('#guide-next').onclick=()=>{if(i===steps.length-1)finish();else{i++;draw()}};const back=d.querySelector('#guide-back');if(back)back.onclick=()=>{i--;draw()}}function open(){i=0;draw();if(!d.open)d.showModal()}d.addEventListener('cancel',e=>{e.preventDefault();finish()});document.addEventListener('click',e=>{if(e.target.closest('#reopen-guide'))open()});try{if(!localStorage.getItem(key))open()}catch{open()}})();

;(()=>{const d=document.createElement('dialog');d.className='welcome-guide';d.setAttribute('aria-label','Localisation météo');document.body.append(d);let serial=0;async function choose(p){const n=++serial;if(p.name==='Ma position GPS'){d.querySelector('#loc-status').textContent='Recherche du nom de la commune…';p=await resolveWeatherCity(p);if(n!==serial||!d.open)return}weatherPlace=p;try{localStorage.setItem('jardeo-weather-place',JSON.stringify(p))}catch{}weatherRequest++;weatherLoading=false;weatherData=null;weatherError='';d.close();render();loadWeather(true)}function open(){serial++;d.innerHTML='<h2>📍 Ma localisation</h2><p>Choisissez votre commune ou autorisez votre appareil à transmettre sa position au service météo Open-Meteo. Le choix est conservé sur cet appareil.</p><button id="loc-gps" class="primary">Utiliser ma position</button><form id="loc-form"><label for="loc-query">Nom de la commune</label><input id="loc-query" required minlength="2" placeholder="Ex. Vendôme"><button type="submit">Rechercher</button></form><p id="loc-status" role="status"></p><div id="loc-results"></div><button id="loc-close">Fermer</button>';const status=d.querySelector('#loc-status'),results=d.querySelector('#loc-results');d.querySelector('#loc-close').onclick=()=>d.close();d.querySelector('#loc-gps').onclick=()=>{const n=++serial;if(!navigator.geolocation){status.textContent='Géolocalisation indisponible. Recherchez votre commune.';return}status.textContent='Recherche de votre position…';navigator.geolocation.getCurrentPosition(p=>{if(n===serial&&d.open)choose({name:'Ma position GPS',latitude:p.coords.latitude,longitude:p.coords.longitude})},()=>{if(n===serial)status.textContent='Position indisponible ou refusée. Recherchez votre commune.'},{timeout:12000,maximumAge:300000})};d.querySelector('#loc-form').onsubmit=async e=>{e.preventDefault();const n=++serial;results.replaceChildren();status.textContent='Recherche…';try{const q=d.querySelector('#loc-query').value.trim();const r=await fetch('https://geocoding-api.open-meteo.com/v1/search?count=10&language=fr&format=json&name='+encodeURIComponent(q));if(!r.ok)throw Error();const places=(await r.json()).results||[];if(n!==serial||!d.open)return;status.textContent=places.length?'Sélectionnez votre commune :':'Aucune commune trouvée.';for(const p of places){const b=document.createElement('button');b.type='button';b.textContent=[p.name,p.admin2||p.admin1,p.country].filter(Boolean).join(' · ');b.onclick=()=>choose({name:b.textContent,latitude:p.latitude,longitude:p.longitude});results.append(b)}}catch{if(n===serial)status.textContent='Recherche indisponible. Réessayez.'}};if(!d.open)d.showModal()}document.addEventListener('click',e=>{if(e.target.closest('[data-action="weather-location"]'))open()})})();

;if(weatherPlace?.name==='Ma position GPS'){const original=weatherPlace;resolveWeatherCity(original).then(p=>{if(weatherPlace!==original||p.name===original.name)return;weatherPlace=p;try{localStorage.setItem('jardeo-weather-place',JSON.stringify(p))}catch{}render()})}
